def construct():
    """Randomised greedy with restarts, then a plateau-walking local search.

    Greedy alone stalls in the 80s: it paints itself into a corner early. The
    fix is the classic one for maximum-independent-set-like problems — when no
    point can be added, REMOVE a point and try again (a (1,2)-swap / plateau
    walk), so the search can leave a maximal-but-not-maximum configuration."""
    import random
    from itertools import product
    random.seed(1996)
    P = [tuple(v) for v in product(range(3), repeat=6)]
    idx = {p: i for i, p in enumerate(P)}
    # third[i][j] = the point completing the line through P[i], P[j]
    third = [[0] * len(P) for _ in range(len(P))]
    for i, x in enumerate(P):
        for j, y in enumerate(P):
            if i != j:
                third[i][j] = idx[tuple((-(a + b)) % 3 for a, b in zip(x, y))]

    def blocked(S):
        """points that cannot join S without creating a line"""
        bad = set()
        L = list(S)
        for a in range(len(L)):
            for b in range(a + 1, len(L)):
                bad.add(third[L[a]][L[b]])
        return bad

    best = []
    for _ in range(40):
        S = set()
        order = list(range(len(P)))
        random.shuffle(order)
        bad = set()
        for p in order:
            if p in bad or p in S:
                continue
            for q in S:
                bad.add(third[p][q])
            S.add(p)
        # plateau walk: drop a few, refill, keep if not worse
        for _ in range(3000):
            T = set(S)
            for _ in range(random.choice([1, 1, 2])):
                if T:
                    T.discard(random.choice(list(T)))
            bad = blocked(T)
            cand = [p for p in range(len(P)) if p not in T and p not in bad]
            random.shuffle(cand)
            for p in cand:
                if p in blocked(T):
                    continue
                T.add(p)
            if len(T) >= len(S):
                S = T
        if len(S) > len(best):
            best = list(S)
    return [list(P[i]) for i in best]

def construct():
    """PRODUCT CONSTRUCTION (algebra lens), not search.

    Caps multiply: if A is a cap in F_3^a and B a cap in F_3^b, then A x B is a
    cap in F_3^(a+b) — a line in the product projects to a line-or-point in each
    factor, and it cannot be a point in both. Known maxima: cap(1)=2, cap(5)=45.
    So cap(6) >= 2 * 45 = 90 WITHOUT ANY SEARCH, beating the annealer's 84.

    We find the 45-cap in F_3^5 by exhaustive-ish local search (small space),
    then take the product with {0,1} in the last coordinate.
    """
    import random
    from itertools import product
    random.seed(7)
    P5 = [tuple(v) for v in product(range(3), repeat=5)]
    idx = {p: i for i, p in enumerate(P5)}
    third = [[0] * len(P5) for _ in range(len(P5))]
    for i, x in enumerate(P5):
        for j, y in enumerate(P5):
            if i != j:
                third[i][j] = idx[tuple((-(a + b)) % 3 for a, b in zip(x, y))]

    def blocked(S):
        bad = set()
        L = list(S)
        for a in range(len(L)):
            for b in range(a + 1, len(L)):
                bad.add(third[L[a]][L[b]])
        return bad

    best5 = []
    for _ in range(60):
        S = set()
        order = list(range(len(P5)))
        random.shuffle(order)
        bad = set()
        for p in order:
            if p in bad or p in S:
                continue
            for q in S:
                bad.add(third[p][q])
            S.add(p)
        for _ in range(2000):
            T = set(S)
            for _ in range(random.choice([1, 1, 2])):
                if T:
                    T.discard(random.choice(list(T)))
            bad = blocked(T)
            cand = [p for p in range(len(P5)) if p not in T and p not in bad]
            random.shuffle(cand)
            for p in cand:
                if p not in blocked(T):
                    T.add(p)
            if len(T) >= len(S):
                S = T
        if len(S) > len(best5):
            best5 = list(S)

    cap5 = [P5[i] for i in best5]
    # product with the 2-point cap {0,1} in a 6th coordinate
    return [list(v) + [c] for v in cap5 for c in (0, 1)]
